/**
 * 联合取样申请：原子预留各母样数量，任一余额不足或键冲突则整单失败，无预留、不占键。
 */
@Transactional
public StoredResponse apply(String actorId, SamplingApplyRequest request, String requestHash) {
    Optional<StoredResponse> replay = checkReplay(request.commandKey(), requestHash);
    if (replay.isPresent()) {
        return replay.get();
    }
    List<SamplingItemInput> items = sortedItems(request);
    // aliquotKey 不得与既有子样申请或证物键冲突。
    if (samplingOrderRepository.findByAliquotKey(request.aliquotKey()).isPresent()) {
        throw ApiException.conflict("aliquotKey 已被联合取样申请占用: " + request.aliquotKey());
    }
    if (evidenceRepository.findByKey(request.aliquotKey()).isPresent()) {
        throw ApiException.conflict("aliquotKey 与既有证物键冲突: " + request.aliquotKey());
