        throw ApiException.conflict("aliquotKey 与既有证物键冲突: " + request.aliquotKey());
    }
    // 未持锁的快速预判：同 requestId 换序重放/异参尽早给出结果。
    Optional<SamplingOrder> preExisting = samplingOrderRepository
            .findByRequestId(request.requestId());
    if (preExisting.isPresent()) {
        return handleExistingRequest(preExisting.get(), request, actorId, items);
    }

    String fingerprint = fingerprint(actorId, request.aliquotKey(), items);
    LocalDateTime now = LocalDateTime.now();
    // 按母样键排序后逐件成对锁定证物行与母样行并条件预留；任一失败抛错，整单回滚。
    List<LockedMother> locked = new java.util.ArrayList<>();
    for (SamplingItemInput item : items) {
        Evidence evidence = evidenceRepository.findByKeyForUpdate(item.sampleKey())
                .orElseThrow(() -> ApiException.notFound("母样证物不存在: " + item.sampleKey()));
        requireUsableMotherEvidence(evidence, actorId, item.sampleKey());
        MotherSample mother = motherSampleRepository.findByKeyForUpdate(item.sampleKey())
                .orElseThrow(() -> ApiException.notFound("母样未登记总量: " + item.sampleKey()));
        if (!motherSampleRepository.reserve(item.sampleKey(), item.qty(), now)) {
            throw ApiException.unprocessable(
                    "母样可用余额不足，整单预留失败: " + item.sampleKey());
        }
        MotherSample afterReserve = motherSampleRepository.findByKey(item.sampleKey()).orElseThrow();
        locked.add(new LockedMother(
                new SamplingItem(null, request.requestId(), item.sampleKey(), item.qty(),
                        mother.unit(), afterReserve.version(), evidence.version(),
                        actorId, evidence.status().name(), now),
                evidence, mother));
    }
    // 持锁后复查并发提交的同 requestId 申请，重放先提交事务的首次结果。
    Optional<SamplingOrder> concurrent = samplingOrderRepository
            .findByRequestId(request.requestId());
    if (concurrent.isPresent()) {
        SamplingOrder existing = concurrent.get();
        if (!existing.requestFingerprint().equals(fingerprint)) {
            throw ApiException.conflict("requestId 已被不同参数集合使用: " + request.requestId());
        }
        return replayStoredCommand(existing.commandKey());
    }
    samplingOrderRepository.insert(request.requestId(), request.aliquotKey(), actorId,
            fingerprint, request.commandKey(), now);
    for (LockedMother lm : locked) {
        SamplingItem item = lm.item();
        samplingItemRepository.insert(request.requestId(), item.sampleKey(), item.qty(),
                item.unit(), item.sampleVersion(), item.evidenceVersion(),
                item.custodianSnapshot(), item.sealStatusSnapshot(), now);
    }
    SamplingOrderView view = buildOrderView(
            samplingOrderRepository.findByRequestId(request.requestId()).orElseThrow());
    return record(request.commandKey(), OP_SAMPLING_APPLY, actorId, requestHash, 201, view);
}

