        assertThat(mother(mothers[0]).get("availableQty").asLong()).isEqualTo(100);
        assertThat(mother(mothers[1]).get("reservedQty").asLong()).isZero();

        // 终态后拒绝/确认均 409
        assertThat(review("reject", "carol", requestId, uniqueKey("CMD"), null, null, null)
