        versions.put(mothers[1], pending.get("items").get(1).get("sampleVersion").asLong());
        confirmSecond("carol", requestId, 1, versions);

        // 子样登记为母样：422
        assertThat(registerMother("alice", aliquotKey, 10, "ML", uniqueKey("CMD"))
